const config: runtime.GetPrismaClientConfig = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// LumiTrack — Schema Prisma\n// Banco de dados: PostgreSQL\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// ENUMS\n// ─────────────────────────────────────────────────────────────────────────────\n\n// Pessoa física (residencial) vs. pessoa jurídica (comercial/industrial)\nenum UserType {\n  INDIVIDUAL // Pessoa física\n  COMPANY // Pessoa jurídica\n}\n\n// Tipo de instalação elétrica — impacta cálculos de consumo e custo\nenum ElectricalSystemType {\n  MONOPHASIC // Monofásico (1 fase)\n  BIPHASIC // Bifásico (2 fases)\n  TRIPHASIC // Trifásico (3 fases)\n}\n\n// Canal pelo qual o token foi emitido — mobile não expira, web expira\nenum TokenChannel {\n  WEB\n  MOBILE\n}\n\n// RBAC mínimo (#16 — A01/Art. 48): distingue usuários comuns de\n// administradores. Sempre lida do banco a cada requisição (nunca um claim do\n// JWT) — ver shared/middlewares/authenticate.ts — para que promover/rebaixar\n// um admin tenha efeito imediato, sem exigir novo login. Documento de design\n// para um sistema de permissões mais extensível: docs/RBAC_DESIGN.md.\nenum Role {\n  USER\n  ADMIN\n\n  @@map(\"role\")\n}\n\n// Eventos de segurança registrados no audit log (#08 — A09/Art. 46).\nenum AuditAction {\n  LOGIN\n  LOGOUT\n  ACCESS_DENIED\n  USER_CREATE\n  USER_UPDATE\n  USER_DELETE\n  PROPERTY_CREATE\n  PROPERTY_UPDATE\n  PROPERTY_DELETE\n  DATA_EXPORT\n  MFA_ENABLED\n  MFA_DISABLED\n  REFRESH_TOKEN_REUSE_DETECTED\n  ADMIN_AUDIT_LOG_VIEW\n\n  @@map(\"audit_action\")\n}\n\nenum AuditOutcome {\n  SUCCESS\n  FAILURE\n\n  @@map(\"audit_outcome\")\n}\n\n// A qual nível da hierarquia um medidor (e, por consequência, a agregação de\n// consumo e os alertas) pertence. Um medidor é vinculado a exatamente um alvo.\nenum TargetType {\n  PROPERTY\n  AREA\n  DEVICE\n}\n\n// Classe de faturamento do Grupo B (baixa tensão) — REN 1.000/2021.\n// B1 residencial, B2 rural, B3 demais (comércio/serviços/pequena indústria).\n// Grupo A (alta/média tensão, tarifa binômia) fica para uma fase futura.\nenum BillingClass {\n  B1\n  B2\n  B3\n}\n\n// Bandeira tarifária vigente (sinal mensal de custo de geração da ANEEL).\n// RED_P1/RED_P2 = vermelha patamar 1/2.\nenum TariffFlag {\n  GREEN\n  YELLOW\n  RED_P1\n  RED_P2\n}\n\nenum IoTProtocol {\n  MQTT\n  MODBUS_TCP\n  MODBUS_RTU\n  ETHERNET_IP\n  PROFIBUS\n  PROFINET\n  RS232\n  RS485\n\n  @@map(\"iot_protocol\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// USUÁRIO\n// ─────────────────────────────────────────────────────────────────────────────\n\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String // hash bcrypt\n  userType  UserType\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // RBAC mínimo (#16 — A01/Art. 48). Ver enum Role acima.\n  role Role @default(USER)\n\n  // Consentimento LGPD (Art. 7º/8º) — registrado no cadastro.\n  // consentVersion identifica qual versão da Política de Privacidade/Termos\n  // foi aceita, permitindo solicitar reaceite quando o documento mudar.\n  consentedAt    DateTime?\n  consentVersion String?\n\n  // Campos exclusivos de pessoa física\n  firstName     String?\n  lastName      String?\n  // cpf armazena o valor criptografado (AES-256-GCM, ver shared/crypto/encryption.ts)\n  // — não pode ser @unique porque o IV aleatório faz o mesmo CPF gerar\n  // ciphertext diferente a cada criptografia. cpfBlindIndex (HMAC-SHA256,\n  // determinístico) é quem garante unicidade e permite busca por igualdade.\n  cpf           String?\n  cpfBlindIndex String? @unique\n\n  // Campos exclusivos de pessoa jurídica\n  companyName    String?\n  // cnpj armazena o valor criptografado — mesma lógica do cpf acima.\n  cnpj           String?\n  cnpjBlindIndex String? @unique\n  tradeName      String?\n\n  // MFA opcional via TOTP (#12 — A06/A07). mfaSecret armazena o segredo\n  // criptografado (AES-256-GCM, chave própria — ver\n  // shared/crypto/mfaEncryption.ts), nunca em texto claro. mfaEnabled\n  // controla se o segundo fator é exigido no login — fica false até o\n  // usuário confirmar o setup com um código válido.\n  mfaEnabled Boolean @default(false)\n  mfaSecret  String?\n\n  // Relacionamentos\n  properties     Property[]\n  tokens         AuthToken[]\n  refreshTokens  RefreshToken[]\n  passwordResets PasswordReset[]\n  alerts         Alert[]\n  auditLogs      AuditLog[]\n  mfaBackupCodes MfaBackupCode[]\n\n  @@map(\"users\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// AUTENTICAÇÃO E SEGURANÇA\n// ─────────────────────────────────────────────────────────────────────────────\n\n// Armazena tokens emitidos para permitir revogação (logout e expiração).\nmodel AuthToken {\n  id        String       @id @default(uuid())\n  userId    String\n  token     String       @unique\n  channel   TokenChannel\n  expiresAt DateTime? // null = mobile (não expira por tempo)\n  revokedAt DateTime? // null = ainda válido\n  createdAt DateTime     @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([token])\n  @@index([userId])\n  @@map(\"auth_tokens\")\n}\n\n// Refresh token da sessão WEB (#14 — A06). Token opaco (randomBytes), nunca\n// um JWT — só é validado via lookup no banco, nunca decodificado client-side.\n// Rotacionado a cada uso: replacedByTokenId encadeia a linhagem, permitindo\n// detectar reuso de um token já trocado (sinal de roubo — ver auth.service.ts).\n// Existe só para o canal WEB; MOBILE já tem token de 90 dias, sem refresh.\nmodel RefreshToken {\n  id                String    @id @default(uuid())\n  userId            String\n  token             String    @unique // hash SHA-256 do valor opaco — nunca o valor puro\n  expiresAt         DateTime\n  revokedAt         DateTime? // null = ainda válido\n  replacedByTokenId String?   @unique\n  createdAt         DateTime  @default(now())\n\n  user            User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  replacedByToken RefreshToken? @relation(\"RefreshTokenRotation\", fields: [replacedByTokenId], references: [id], onDelete: SetNull)\n  replacesToken   RefreshToken? @relation(\"RefreshTokenRotation\")\n\n  @@index([token])\n  @@index([userId])\n  @@map(\"refresh_tokens\")\n}\n\nmodel PasswordReset {\n  id        String    @id @default(uuid())\n  userId    String\n  token     String    @unique\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([token])\n  @@map(\"password_resets\")\n}\n\n// Códigos de backup do MFA (#12) — uso único, gerados em lote no momento do\n// setup e exibidos uma única vez ao usuário (só o hash bcrypt fica\n// persistido). Cobrem o caso de perda do dispositivo com o app autenticador.\nmodel MfaBackupCode {\n  id        String    @id @default(uuid())\n  userId    String\n  codeHash  String // hash bcrypt — mesmo padrão usado para a senha\n  usedAt    DateTime? // null = ainda não usado\n  createdAt DateTime  @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"mfa_backup_codes\")\n}\n\n// Trilha de auditoria (#08 — A09/Art. 46): login/logout, acesso negado (403)\n// e CRUD de dados pessoais (User/Property). `userId` é nullable e usa\n// `onDelete: SetNull` — diferente das outras relações com User (que usam\n// Cascade) — de propósito: o registro de auditoria deve sobreviver à\n// exclusão da conta (é exatamente o tipo de evento que o Art. 48 pede pra\n// conseguir reconstruir depois de um incidente). `metadata` guarda contexto\n// adicional sem incluir valores sensíveis (ex.: nomes de campos alterados,\n// nunca os valores em si).\nmodel AuditLog {\n  id           String       @id @default(uuid())\n  userId       String?\n  action       AuditAction\n  outcome      AuditOutcome\n  resourceType String?\n  resourceId   String?\n  ipAddress    String?\n  userAgent    String?\n  metadata     Json?\n  createdAt    DateTime     @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([userId])\n  @@index([action])\n  @@index([createdAt])\n  @@index([outcome])\n  @@index([resourceType])\n  @@map(\"audit_logs\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// DISTRIBUIDORA DE ENERGIA\n// ─────────────────────────────────────────────────────────────────────────────\n\n// Catálogo global de distribuidoras (somente leitura, populado via seed).\n// Deixou de ser cadastrada por usuário: passa a ser um catálogo compartilhado\n// com dados tarifários reais do Grupo B. `electricalSystem`/`workingVoltage`\n// migraram para Property (são características da unidade consumidora, não da\n// concessionária). O custo por kWh agora é decomposto em TUSD + TE + tributos\n// (cálculo \"por dentro\"), aplicado pelo TariffService.\nmodel EnergyDistributor {\n  id    String @id @default(uuid())\n  name  String\n  cnpj  String @unique\n  state String // UF (ex.: \"SP\", \"SC\") — define a alíquota de ICMS aplicável\n\n  // Parcelas da tarifa sem tributos, em BRL/kWh. TUSD = uso do sistema de\n  // distribuição; TE = energia. A tarifa efetiva ao consumidor é\n  // (tusd + te) / (1 − (icms + pis + cofins)) + bandeira.\n  tusdPerKwh Decimal @db.Decimal(10, 6)\n  tePerKwh   Decimal @db.Decimal(10, 6)\n\n  // Alíquotas nominais de tributos (formato decimal, ex.: 0.1800 = 18%).\n  // ICMS varia por UF; PIS/COFINS são federais (~1,65% / ~7,6%).\n  icmsRate   Decimal @db.Decimal(5, 4)\n  pisRate    Decimal @db.Decimal(5, 4)\n  cofinsRate Decimal @db.Decimal(5, 4)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  properties Property[]\n\n  @@map(\"energy_distributors\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// HIERARQUIA: PROPRIEDADE → ÁREA → APARELHO\n// ─────────────────────────────────────────────────────────────────────────────\n\nmodel Property {\n  id            String  @id @default(uuid())\n  userId        String\n  distributorId String\n  name          String\n  address       String?\n  city          String?\n  state         String?\n  zipCode       String?\n\n  // Sistema elétrico da unidade consumidora (migrou da distribuidora): define o\n  // piso de disponibilidade (30/50/100 kWh) aplicado na tarifação mensal.\n  electricalSystem ElectricalSystemType\n\n  // Classe de faturamento Grupo B (default residencial B1).\n  billingClass BillingClass @default(B1)\n\n  // CIP/COSIP municipal (contribuição de iluminação pública) em BRL — valor fixo\n  // somado FORA da base de tributos. Opcional: nem todo município cobra.\n  publicLightingFeeBrl Decimal? @db.Decimal(10, 2)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user        User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  distributor EnergyDistributor @relation(fields: [distributorId], references: [id])\n  areas       Area[]\n  meter       Meter?\n\n  @@map(\"properties\")\n}\n\nmodel Area {\n  id          String   @id @default(uuid())\n  propertyId  String\n  name        String\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  property Property @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  devices  Device[]\n  meter    Meter?\n\n  @@map(\"areas\")\n}\n\nmodel Device {\n  id         String   @id @default(uuid())\n  areaId     String\n  name       String\n  brand      String?\n  model      String?\n  powerWatts Float? // potência nominal em Watts\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  area  Area   @relation(fields: [areaId], references: [id], onDelete: Cascade)\n  meter Meter?\n\n  @@map(\"devices\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// MEDIDORES IoT E LEITURAS\n// ─────────────────────────────────────────────────────────────────────────────\n\n// Medidor IoT vinculado a exatamente um alvo (Property, Area ou Device).\n// Exatamente um dos FKs propertyId/areaId/deviceId estará preenchido, coerente\n// com targetType. O `@unique` em cada FK garante no máximo 1 medidor por alvo.\n// A config de conexão migrou do antigo IoTDeviceConfig (que era 1:1 com Device).\n// Posse é resolvida via alvo → Property → User (não há userId direto aqui).\nmodel Meter {\n  id         String     @id @default(uuid())\n  name       String\n  targetType TargetType\n  propertyId String?    @unique\n  areaId     String?    @unique\n  deviceId   String?    @unique\n\n  // Configuração de conexão do protocolo IoT.\n  protocol IoTProtocol\n  host     String?\n  port     Int?\n  topic    String? // para MQTT\n  address  String? // para Modbus/RS485\n  extra    Json? // configurações extras específicas do protocolo\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  property Property?      @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  area     Area?          @relation(fields: [areaId], references: [id], onDelete: Cascade)\n  device   Device?        @relation(fields: [deviceId], references: [id], onDelete: Cascade)\n  readings MeterReading[]\n  alerts   Alert[]\n\n  @@map(\"meters\")\n}\n\n// Uma linha por medidor por minuto. `minuteStart` é o instante truncado ao\n// minuto (UTC, timestamp de recebimento no backend). As médias são ponderadas\n// por tempo; `secondsCovered` permite um merge idempotente no upsert quando o\n// rollup roda mais de uma vez no mesmo minuto (ex.: restart do servidor).\nmodel MeterReading {\n  id             String   @id @default(uuid())\n  meterId        String\n  minuteStart    DateTime\n  kwhConsumed    Float\n  avgVoltage     Float\n  avgCurrent     Float\n  avgPowerW      Float\n  avgPowerFactor Float\n  sampleCount    Int\n  secondsCovered Float\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  meter Meter @relation(fields: [meterId], references: [id], onDelete: Cascade)\n\n  @@unique([meterId, minuteStart])\n  @@map(\"meter_readings\")\n}\n\n// Configuração singleton (id fixo = 1) da bandeira tarifária vigente e dos\n// valores de acréscimo por 100 kWh de cada bandeira (R$/100 kWh).\nmodel TariffFlagConfig {\n  id              Int        @id @default(1)\n  currentFlag     TariffFlag @default(GREEN)\n  greenPer100Kwh  Decimal    @db.Decimal(10, 4)\n  yellowPer100Kwh Decimal    @db.Decimal(10, 4)\n  redP1Per100Kwh  Decimal    @db.Decimal(10, 4)\n  redP2Per100Kwh  Decimal    @db.Decimal(10, 4)\n  updatedAt       DateTime   @updatedAt\n\n  @@map(\"tariff_flag_config\")\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// ALERTAS POR FAIXA DE POTÊNCIA\n// ─────────────────────────────────────────────────────────────────────────────\n\n// Alerta por faixa de potência ativa de um medidor: dispara quando a potência\n// sai da faixa [ref × (1 − tol%), ref × (1 + tol%)]. Avaliado amostra a amostra\n// pelo AlertEvaluator; cada episódio de disparo vira um AlertTriggerEvent.\nmodel Alert {\n  id               String  @id @default(uuid())\n  userId           String\n  meterId          String\n  name             String\n  referencePowerKw Float // potência de referência em kW\n  tolerancePercent Float // tolerância em % (ex.: 2 → faixa de ±2%)\n  enabled          Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user   User                @relation(fields: [userId], references: [id], onDelete: Cascade)\n  meter  Meter               @relation(fields: [meterId], references: [id], onDelete: Cascade)\n  events AlertTriggerEvent[]\n\n  @@index([meterId])\n  @@map(\"alerts\")\n}\n\n// Histórico de episódios de disparo de um alerta. Persistido no FIM do episódio\n// (quando a potência normaliza, ou o alerta é desabilitado/excluído durante o\n// disparo), com a duração e as estatísticas de potência do período.\nmodel AlertTriggerEvent {\n  id              String   @id @default(uuid())\n  alertId         String\n  startedAt       DateTime\n  endedAt         DateTime\n  durationSeconds Int\n  minPowerW       Float\n  maxPowerW       Float\n  avgPowerW       Float\n  sampleCount     Int\n  createdAt       DateTime @default(now())\n\n  alert Alert @relation(fields: [alertId], references: [id], onDelete: Cascade)\n\n  @@index([alertId, startedAt])\n  @@map(\"alert_trigger_events\")\n}\n",
  "runtimeDataModel": {
    "models": {},
    "enums": {},
    "types": {}
  },
  "parameterizationSchema": {
    "strings": [],
    "graph": ""
  }
}

